package io.github.diodeme.ji.testkit;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicReference;

/** Manually advanced clock for deterministic tests. */
public final class DynamicClock extends Clock {
    private final AtomicReference<Instant> now;
    private final ZoneId zone;

    public DynamicClock(Instant initial, ZoneId zone) {
        now = new AtomicReference<>(Objects.requireNonNull(initial, "initial"));
        this.zone = Objects.requireNonNull(zone, "zone");
    }

    @Override
    public ZoneId getZone() {
        return zone;
    }

    @Override
    public Clock withZone(ZoneId newZone) {
        return new DynamicClock(instant(), newZone);
    }

    @Override
    public Instant instant() {
        return now.get();
    }

    public Instant advance(Duration duration) {
        Objects.requireNonNull(duration, "duration");
        return now.updateAndGet(value -> value.plus(duration));
    }
}
